<script setup lang="ts">
/**
 * Avatar.Group: a row of overlapping Avatars with a "+N" chip when `max` cuts the set.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { cloneVNode } from 'vue'

import { definedProps, slotted, slottedElements } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/avatar.module.css'

export interface AvatarGroupProps {
  /**
   * Maximum number drawn; the rest become "+N", and omitting it draws all.
   */
  max?: number
  /**
   * The group’s accessible name, such as "Assignees" rather than "Avatars".
   */
  label: string
}

defineOptions({ name: 'AvatarGroup', inheritAttrs: false })

defineProps<AvatarGroupProps>()
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
</script>

<template>
  <div :class="styles.group" role="group" :aria-label="label">
    <template v-for="(node, at) in slottedElements($slots.default, max)" :key="at">
      <component
        :is="
          cloneVNode(
            node,
            definedProps({ label: (node.props ?? {}).label ?? (node.props ?? {}).name }),
          )
        "
      />
    </template>
    <!-- surplus -->
    <span
      v-if="max !== undefined && slotted($slots.default).count > max"
      :class="[styles.avatar, styles.surplus]"
      :data-size="slotted($slots.default).props.size ?? 'md'"
    >
      {{ `+${slotted($slots.default).count - max}` }}
    </span>
  </div>
</template>
